using System;

static class WorkspaceLaunchChecks {
 static readonly DateTime Now=new DateTime(2026,11,3,20,0,0,DateTimeKind.Utc);
 static WorkspaceLaunchWindow Window(int id,string process,string title,string appId=null){return new WorkspaceLaunchWindow{Id=new Guid(id,0,0,new byte[8]).ToString(),Process=process,Title=title,AppId=appId};}
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 public static void Run(){var rule=new WorkspaceApp{id="editor",workspace="4",processPattern="^Code$"};var rules=new[]{rule};var empty=new WorkspaceLaunchWindow[0];var policy=new WorkspaceLaunchPolicy();
  Check(policy.Observe(empty,rules,true,Now).Length==0,"Startup must only seed state");
  var first=Window(1,"Code","Editor");var moves=policy.Observe(new[]{first},rules,true,Now.AddSeconds(1));Check(moves.Length==1&&moves[0].WindowId==first.Id&&moves[0].Workspace=="4","Cold first instance not routed");
  Check(policy.Observe(new[]{first},rules,true,Now.AddSeconds(2)).Length==0,"Existing window routed twice");
  var second=Window(2,"Code","Second document");Check(policy.Observe(new[]{first,second},rules,true,Now.AddSeconds(3)).Length==0,"Second instance moved while app already running");
  rule.workspace="7";Check(policy.Observe(new[]{first,second},rules,true,Now.AddSeconds(4)).Length==0,"Editing pin relocated existing windows");
  policy=new WorkspaceLaunchPolicy();policy.Observe(empty,rules,true,Now);Check(policy.Observe(new[]{second},rules,true,Now.AddSeconds(1)).Length==1,"Tray-only background app blocked first-window assignment");
  policy=new WorkspaceLaunchPolicy();Check(policy.Observe(new[]{first},rules,true,Now).Length==0,"Reconnect moved baseline windows");
  policy.Observe(empty,rules,true,Now.AddSeconds(1));Check(policy.Observe(new[]{second},rules,true,Now.AddSeconds(2)).Length==1,"App did not route after completely exiting");
  var youtube=new WorkspaceApp{id="youtube",workspace="7",processPattern="^chrome$",titlePattern="YouTube$",windowAppId="browser.youtube"};var ytRules=new[]{youtube};var helium=Window(10,"chrome","Work - Helium","browser.helium");var yt=Window(11,"chrome","Playing a video","browser.youtube");
  policy=new WorkspaceLaunchPolicy();policy.Observe(new[]{helium},ytRules,true,Now);moves=policy.Observe(new[]{helium,yt},ytRules,true,Now.AddSeconds(1));Check(moves.Length==1&&moves[0].WindowId==yt.Id,"YouTube confused with shared Helium process");
  var another=Window(12,"chrome","Another video","browser.youtube");Check(policy.Observe(new[]{helium,yt,another},ytRules,true,Now.AddSeconds(2)).Length==0,"Existing YouTube instance not respected");
  policy=new WorkspaceLaunchPolicy();policy.Observe(empty,ytRules,true,Now);var loading=Window(13,"chrome","Loading");Check(policy.Observe(new[]{loading},ytRules,true,Now.AddSeconds(1)).Length==0,"Unidentified browser window moved");loading.AppId="browser.youtube";Check(policy.Observe(new[]{loading},ytRules,true,Now.AddSeconds(2.2)).Length==1,"New web app identity did not settle after more than one retry");
  policy=new WorkspaceLaunchPolicy();policy.Observe(empty,new WorkspaceApp[0],true,Now);policy.Observe(new[]{loading},new WorkspaceApp[0],true,Now.AddSeconds(1));Check(policy.Observe(new[]{loading},ytRules,true,Now.AddSeconds(1.4)).Length==0,"Adding a pin moved an already running app");
  policy=new WorkspaceLaunchPolicy();policy.Observe(empty,ytRules,false,Now);policy.Observe(new[]{loading},ytRules,false,Now.AddSeconds(1));Check(policy.Observe(new[]{loading},ytRules,true,Now.AddSeconds(1.4)).Length==0,"Enabling rules moved running windows");
  var signalRule=new WorkspaceApp{id="signal",workspace="2",processPattern="^Signal$"};var signalRules=new[]{signalRule};var signal=Window(20,"Signal.exe","Signal");policy=new WorkspaceLaunchPolicy();policy.Observe(new[]{helium},signalRules,true,Now);moves=policy.Observe(new[]{helium,signal},signalRules,true,Now.AddSeconds(1));Check(moves.Length==1&&moves[0].WindowId==signal.Id&&moves[0].Workspace=="2","Signal's first window did not route to workspace 2");
  Check(policy.Observe(new[]{helium,signal,Window(21,"Signal","Signal")},signalRules,true,Now.AddSeconds(2)).Length==0,"Another open Signal window must prevent reassignment");
  policy.Observe(new[]{helium},signalRules,true,Now.AddSeconds(3));Check(policy.Observe(new[]{helium,signal},signalRules,true,Now.AddSeconds(4)).Length==1,"Signal reopened from tray did not route");
  policy=new WorkspaceLaunchPolicy();policy.Observe(empty,signalRules,true,Now);policy.Observe(new[]{Window(22,"UnrelatedApp","Loading")},signalRules,true,Now.AddSeconds(1));Check(!policy.HasPending,"Unconfigured apps must not cause settling retries");
  var spotifyRule=new WorkspaceApp{id="spotify",workspace="2",processPattern="^Spotify$"};var spotifyRules=new[]{spotifyRule};var spotifyA=Window(30,"Spotify","Spotify");var spotifyB=Window(31,"Spotify","Spotify Premium");policy=new WorkspaceLaunchPolicy();policy.Observe(empty,spotifyRules,true,Now);moves=policy.Observe(new[]{spotifyA,spotifyB},spotifyRules,true,Now.AddSeconds(1));Check(moves.Length==2&&Array.TrueForAll(moves,m=>m.Workspace=="2"&&m.LaunchPeers.Length==2),"Simultaneous first Spotify windows must not block each other");Check(policy.Observe(new[]{spotifyA,spotifyB,Window(32,"Spotify","Another window")},spotifyRules,true,Now.AddSeconds(2)).Length==0,"An existing Spotify window must still block a later launch");
  policy=new WorkspaceLaunchPolicy();policy.Observe(new[]{spotifyA},spotifyRules,true,Now);moves=policy.Observe(new[]{spotifyB},spotifyRules,true,Now.AddSeconds(1));Check(moves.Length==1,"A closed/replaced Spotify window must not count as another open instance");
  policy=new WorkspaceLaunchPolicy();policy.Observe(empty,spotifyRules,true,Now);var unknown=Window(33,null,"");Check(policy.Observe(new[]{unknown},spotifyRules,true,Now.AddSeconds(1)).Length==0&&policy.HasPending,"Missing initial process identity must get a settling allowance");unknown.Process="Spotify";Check(policy.Observe(new[]{unknown},spotifyRules,true,Now.AddSeconds(5)).Length==1,"Late Spotify process identity was missed");
  policy=new WorkspaceLaunchPolicy();var earlySpotify=Window(40,"Spotify","Spotify Premium");earlySpotify.StartedUtc=Now.AddSeconds(-60);
  moves=policy.Observe(new[]{earlySpotify},spotifyRules,true,Now);Check(moves.Length==1&&moves[0].Workspace=="2","Spotify launched before CC became ready must still route");
  Check(policy.Observe(new[]{earlySpotify},spotifyRules,true,Now.AddSeconds(1)).Length==0,"Startup reconciliation must not route the same window twice");
  var longRunning=Window(41,"Spotify","Spotify Premium");longRunning.StartedUtc=Now.AddHours(-1);policy=new WorkspaceLaunchPolicy();Check(policy.Observe(new[]{longRunning},spotifyRules,true,Now).Length==0,"CC startup must leave long-running app windows in place");
  policy=new WorkspaceLaunchPolicy();policy.Observe(empty,spotifyRules,true,Now);var unknownA=Window(36,null,"");var unknownB=Window(37,null,"");policy.Observe(new[]{unknownA,unknownB},spotifyRules,true,Now.AddSeconds(1));unknownA.Process=unknownB.Process="Spotify";moves=policy.Observe(new[]{unknownA,unknownB},spotifyRules,true,Now.AddSeconds(3));Check(moves.Length==2&&Array.TrueForAll(moves,m=>m.LaunchPeers.Length==2),"Delayed identities from the same initial launch must not block one another");
  policy=new WorkspaceLaunchPolicy();policy.Observe(empty,ytRules,true,Now);var lateIdentity=Window(34,"chrome","Loading");policy.Observe(new[]{lateIdentity},ytRules,true,Now.AddSeconds(1));lateIdentity.AppId="browser.youtube";Check(policy.Observe(new[]{lateIdentity},ytRules,true,Now.AddSeconds(6)).Length==1,"Slow initial app identity must be allowed beyond two seconds");
  policy=new WorkspaceLaunchPolicy();policy.Observe(empty,ytRules,true,Now);var neverIdentified=Window(35,"chrome","Loading");policy.Observe(new[]{neverIdentified},ytRules,true,Now.AddSeconds(1));neverIdentified.AppId="browser.youtube";Check(policy.Observe(new[]{neverIdentified},ytRules,true,Now.AddSeconds(10)).Length==0&&!policy.HasPending,"Identity retry window must remain bounded");
  Console.WriteLine("PASS: first-open-window routing; no moves on pin/config edits, reconnect, second instances or existing app windows; tray-only first-window launches route; shared-browser web-app identity and delayed initial identity. Synthetic snapshots; no real windows moved.");
 }
}
